package com.gestordevendas.api.inventory;
import com.gestordevendas.api.company.Company; import com.gestordevendas.api.product.Product; import com.gestordevendas.api.sale.Sale; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="venda_lote_consumos",schema="api_internal") public class SaleLotConsumption{ @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="empresa_id") private Company company; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="venda_id") private Sale sale; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="produto_id") private Product product; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="lote_id") private InventoryLot lot; @Column(name="quantidade", nullable=false, precision=14, scale=3) private BigDecimal quantity; @Column(name="custo_unitario",nullable=false) private BigDecimal unitCost; protected SaleLotConsumption(){} public static SaleLotConsumption create(Company c,Sale s,Product p,InventoryLot l,BigDecimal q){var x=new SaleLotConsumption();x.id=UUID.randomUUID();x.company=c;x.sale=s;x.product=p;x.lot=l;x.quantity=q;x.unitCost=l.getUnitCost();return x;} public InventoryLot getLot(){return lot;} public BigDecimal getQuantity(){return quantity;} }
